package com.feedback.repository.alert

import com.feedback.mapper.alert.*
import com.feedback.model.po.alert.*
import com.feedback.model.query.alert.*
import org.springframework.stereotype.Repository
import java.time.LocalDateTime

private data class MetricFact(val source:MetricSourcePo,val contents:List<MetricContentPo>,val identities:List<MetricIdentityPo>,val mainLinks:List<MetricClusterLinkPo>,val activeLinks:List<MetricClusterLinkPo>,val sdk:List<MetricSdkChannelPo>)

@Repository
class AlertMetricRepository(private val sources:AlertMetricSourceMapper,private val contents:AlertMetricContentMapper,private val identities:AlertMetricIdentityMapper,private val links:AlertMetricClusterLinkMapper,private val clusters:AlertMetricClusterMapper,private val occurrences:AlertMetricOccurrenceMapper,private val notifications:AlertMetricNotificationMapper,private val batches:AlertMetricImportBatchMapper,private val rows:AlertMetricImportRowMapper,private val ingests:AlertMetricSdkIngestMapper,private val configs:AlertMetricConfigMapper,private val aiTasks:AlertMetricAiTaskMapper,private val jira:AlertMetricJiraMapper,private val sdk:AlertMetricSdkChannelMapper){
 fun sampleSize(start:LocalDateTime,end:LocalDateTime)=sources.countBetween(start,end)
 fun feedbackSpike(start:LocalDateTime,end:LocalDateTime)=facts(start,end).sumOf{it.contents.count(::valid)}.toDouble()
 fun errorRate(start:LocalDateTime,end:LocalDateTime)=percentage(facts(start,end).flatMap{it.contents}.filter(::valid)){it.issueCategory=="BUG"}
 fun criticalRatio(start:LocalDateTime,end:LocalDateTime)=percentage(facts(start,end).flatMap{it.contents}.filter(::valid)){it.severity in setOf("S0","S1")}
 fun sdkCount(start:LocalDateTime,end:LocalDateTime)=occurrences.sdkCountBetween(start,end);fun sdkNonRateLimitFailureRate(start:LocalDateTime,end:LocalDateTime)=occurrences.sdkNonRateLimitFailureBetween(start,end);fun sdkRateLimitRate(start:LocalDateTime,end:LocalDateTime)=occurrences.sdkRateLimitBetween(start,end)
 fun channelMaxStale(end:LocalDateTime)=sources.channelStaleAt(end).maxOfOrNull{it.stale}?:999999.0
 fun importFailed(start:LocalDateTime,end:LocalDateTime)=batches.failedBetween(start,end);fun importRows(start:LocalDateTime,end:LocalDateTime)=batches.rowsBetween(start,end);fun importFailureRate(start:LocalDateTime,end:LocalDateTime)=batches.failureBetween(start,end);fun mappingRows(start:LocalDateTime,end:LocalDateTime)=rows.countBetween(start,end);fun mappingErrorRate(start:LocalDateTime,end:LocalDateTime)=rows.errorBetween(start,end)
 fun maskingAttempts(start:LocalDateTime,end:LocalDateTime)=facts(start,end).sumOf{f->f.contents.count{!it.deleted}}.toDouble();fun maskingFailureRate(start:LocalDateTime,end:LocalDateTime)=percentage(facts(start,end).flatMap{it.contents}.filter{!it.deleted}){it.maskingStatus=="FAIL"};fun maskingBacklog(start:LocalDateTime,end:LocalDateTime)=facts(start,end).sumOf{f->f.contents.count{!it.deleted&&it.maskingStatus in setOf("PENDING","REVIEW_NEEDED")}}.toDouble()
 fun maskingOldestPending(start:LocalDateTime,end:LocalDateTime)=facts(start,end).filter{f->f.contents.any{!it.deleted&&it.maskingStatus in setOf("PENDING","REVIEW_NEEDED")}}.mapNotNull{it.source.ingestTime}.minOrNull()?.let{java.time.Duration.between(it,end).toMinutes().toDouble()}?:0.0
 fun qualityRows(start:LocalDateTime,end:LocalDateTime)=batches.qualityRowsBetween(start,end);fun qualityScore(start:LocalDateTime,end:LocalDateTime)=batches.qualityScoreBetween(start,end);fun openIdempotencyConflicts(start:LocalDateTime,end:LocalDateTime)=occurrences.openIdempotencyBetween(start,end)
 fun urgentBreaches(start:LocalDateTime,end:LocalDateTime)=ingests.urgentBetween(start,end);fun failedRecoveryBreaches(start:LocalDateTime,end:LocalDateTime)=ingests.failedBetween(start,end);fun sdkVolume(end:LocalDateTime)=occurrences.sdkVolumeBefore(end)
 fun negativeSentimentCount(end:LocalDateTime)=facts(end.minusHours(1),end).count{f->f.contents.any{valid(it)&&it.sentiment=="NEGATIVE"}}.toDouble()
 fun contactEscalationCandidates(start:LocalDateTime,end:LocalDateTime)=contactCandidates(facts(start,end,identity=true,main=true))
 fun resolvedReoccurrenceCandidates(start:LocalDateTime,end:LocalDateTime,criticalOnly:Boolean=false)=resolvedCandidates(facts(start,end,identity=true,active=true),criticalOnly)
 fun contentErrorCandidates(start:LocalDateTime,end:LocalDateTime)=clusterIdentityCandidates(facts(start,end,identity=true,main=true).filter{f->f.contents.any{valid(it)&&it.issueCategory=="CONTENT_ERROR"}},3,2)
 fun redblackFloodCandidates(start:LocalDateTime,end:LocalDateTime)=clusterIdentityCandidates(facts(start,end,identity=true,main=true).filter{f->f.source.sourceChannel=="REDBLACK"&&f.contents.any(::valid)},5,3)
 fun longUnresolvedClusters(end:LocalDateTime):Double{val all=facts(end.minusDays(7),end,active=true);val clusterMap=clusterMap(all.flatMap{it.activeLinks}.map{it.clusterId});val cutoff=end.minusDays(30);return all.filter{it.contents.any(::valid)}.flatMap{it.activeLinks}.map{it.clusterId}.distinct().count{id->clusterMap[id]?.let{it.status in setOf("ACTIVE","MITIGATING","REOPENED")&&it.createdAt?.let{d->d<=cutoff}==true}==true}.toDouble()}
 fun devicePersistentCandidates(end:LocalDateTime)=devicePersistent(facts(end.minusDays(7),end,identity=true,main=true),end.minusHours(24))
 fun highRiskCrossChannel(start:LocalDateTime,end:LocalDateTime)=clusterSourceCandidates(facts(start,end,main=true).filter{f->f.contents.any{valid(it)&&it.severity in setOf("S0","S1")}},3,2)
 fun criticalClusterSurge(start:LocalDateTime,end:LocalDateTime)=clusterSourceCandidates(facts(start,end,main=true).filter{f->f.contents.any{valid(it)&&it.severity in setOf("S0","S1")}},10,2)
 fun publicNegativeFlare(start:LocalDateTime,end:LocalDateTime)=publicNegative(facts(start,end,main=true))
 fun userRiskCount(start:LocalDateTime,end:LocalDateTime,kind:String)=userRisk(facts(start,end),kind)
 fun deviceModelWideFailure(start:LocalDateTime,end:LocalDateTime)=deviceWide(facts(start,end,identity=true,sdkData=true))
 fun feedbackSpike(minutes:Int)=facts(minutes).sumOf{f->f.contents.count(::valid)}.toDouble()
 fun errorRate(minutes:Int)=percentage(facts(minutes).flatMap{it.contents}.filter(::valid)){it.issueCategory=="BUG"}
 fun criticalRatio(minutes:Int)=percentage(facts(minutes).flatMap{it.contents}.filter(::valid)){it.severity in setOf("S0","S1")}
 fun dataInterruption()=sources.maxStale()?:0.0
 fun notificationBacklog()=notifications.backlog();fun notificationFailureRate(minutes:Int)=occurrences.notificationFailureRate(minutes);fun notificationOldestPending()=notifications.oldestPending();fun notificationDeadLetters()=notifications.deadLetters()
 fun sdkCount(minutes:Int)=occurrences.sdkCount(minutes);fun sdkFailureRate(minutes:Int)=occurrences.sdkFailureRate(minutes);fun sdkNonRateLimitFailureRate(minutes:Int)=occurrences.sdkNonRateLimitFailureRate(minutes);fun sdkRateLimitRate(minutes:Int)=occurrences.sdkRateLimitRate(minutes)
 fun channelMaxStale()=sources.channelStale().maxOfOrNull{it.stale}?:999999.0;fun tableChannelMaxStale()=batches.maxChannelStale()?:999999.0
 fun importFailed(minutes:Int)=batches.failed(minutes);fun importRows(minutes:Int)=batches.rowCount(minutes);fun importFailureRate(minutes:Int)=batches.failureRate(minutes);fun mappingRows(minutes:Int)=rows.count(minutes);fun mappingErrorRate(minutes:Int)=rows.errorRate(minutes)
 fun maskingAttempts(minutes:Int)=facts(minutes).sumOf{it.contents.size}.toDouble();fun maskingFailureRate(minutes:Int)=percentage(facts(minutes).flatMap{it.contents}){it.maskingStatus=="FAIL"};fun maskingBacklog()=contents.backlog()
 fun maskingOldestPending():Double{var after=0L;var oldest:LocalDateTime?=null;while(true){val ids=contents.pendingSourcePage(after,500);if(ids.isEmpty())break;sources.byIds(ids.distinct()).forEach{row->row.ingestTime?.let{if(oldest==null||it<oldest)oldest=it}};after=ids.last();if(ids.size<500)break};return oldest?.let{java.time.Duration.between(it,LocalDateTime.now()).toMinutes().toDouble()}?:0.0}
 fun qualityRows(minutes:Int)=batches.qualityRows(minutes);fun qualityScore(minutes:Int)=batches.qualityScore(minutes);fun openIdempotencyConflicts()=occurrences.openIdempotencyConflicts()
 fun urgentBreaches()=ingests.urgentBreaches();fun failedRecoveryBreaches()=ingests.failedRecoveryBreaches();fun sdkVolume30m()=occurrences.sdkVolume30m()
 fun aiConsecutiveFailures()=maxOf(configs.reportHealth()?.recordVersion?:0,aiTasks.latestStatuses().count{it=="FAILED"}).toDouble()
 fun maskingConsecutiveFailures():Double=facts(15).sortedWith(compareByDescending<MetricFact>{it.source.ingestTime}.thenByDescending{it.source.id}).flatMap{it.contents}.take(5).count{it.maskingStatus=="FAIL"}.toDouble()

 fun negativeSentimentCount()=facts(60).filter{f->f.contents.any{valid(it)&&it.sentiment=="NEGATIVE"}}.map{it.source.id}.distinct().size.toDouble()
 fun contactEscalationCandidates()=contactCandidates(facts(1440,identity=true,main=true))
 fun resolvedReoccurrenceCandidates(criticalOnly:Boolean=false)=resolvedCandidates(facts(1440,identity=true,active=true),criticalOnly)
 fun contentErrorCandidates():Double=clusterIdentityCandidates(facts(240,identity=true,main=true).filter{f->f.contents.any{valid(it)&&it.issueCategory=="CONTENT_ERROR"}},3,2)
 fun redblackFloodCandidates():Double=clusterIdentityCandidates(facts(60,identity=true,main=true).filter{f->f.source.sourceChannel=="REDBLACK"&&f.contents.any(::valid)},5,3)
 fun devicePersistentCandidates()=devicePersistent(facts(10080,identity=true,main=true),LocalDateTime.now().minusHours(24))
 fun highRiskCrossChannel()=clusterSourceCandidates(facts(60,main=true).filter{f->f.contents.any{valid(it)&&it.severity in setOf("S0","S1")}},3,2)
 fun criticalClusterSurge()=clusterSourceCandidates(facts(60,main=true).filter{f->f.contents.any{valid(it)&&it.severity in setOf("S0","S1")}},10,2)
 fun publicNegativeFlare()=publicNegative(facts(60,main=true))
 fun userRiskCount(minutes:Int,kind:String)=userRisk(facts(minutes),kind)
 fun deviceModelWideFailure()=deviceWide(facts(60,identity=true,sdkData=true))
 fun longUnresolvedClusters():Double{val all=facts(10080,active=true);val clusterMap=clusterMap(all.flatMap{it.activeLinks}.map{it.clusterId});val cutoff=LocalDateTime.now().minusDays(30);return all.filter{it.contents.any(::valid)}.flatMap{it.activeLinks}.map{it.clusterId}.distinct().count{id->clusterMap[id]?.let{it.status in setOf("ACTIVE","MITIGATING","REOPENED")&&it.createdAt?.let{d->d<=cutoff}==true}==true}.toDouble()}
 fun longUnresolvedJira():Double{val minima=mutableMapOf<Long,LocalDateTime>();var after=0L;val cutoff=LocalDateTime.now().minusDays(30);while(true){val page=jira.unresolvedPage(after,500);if(page.isEmpty())break;val sourceMap=sources.byIds(page.map{it.sourceId}.distinct()).associateBy{it.id};val contentMap=if(sourceMap.isEmpty())emptyMap() else contents.bySources(sourceMap.keys.toList()).groupBy{it.sourceId};val linkMap=if(sourceMap.isEmpty())emptyMap() else links.mainBySources(sourceMap.keys.toList()).groupBy{it.sourceId};page.forEach{j->val s=sourceMap[j.sourceId]?:return@forEach;if(s.sourceChannel!="JIRA"||contentMap[s.id].orEmpty().none(::valid))return@forEach;val time=j.createdAt?:s.sourceEventTime?:s.ingestTime?:return@forEach;linkMap[s.id].orEmpty().forEach{l->if(time<=(minima[l.clusterId]?:LocalDateTime.MAX))minima[l.clusterId]=time}};after=page.last().rawId;if(page.size<500)break};return minima.values.count{it<=cutoff}.toDouble()}

 private fun facts(minutes:Int,identity:Boolean=false,main:Boolean=false,active:Boolean=false,sdkData:Boolean=false):List<MetricFact>{val result=mutableListOf<MetricFact>();var after=0L;while(true){val page=sources.pageSince(minutes,after,500);if(page.isEmpty())break;val ids=page.map{it.id};val c=contents.bySources(ids).groupBy{it.sourceId};val i=if(identity)identities.bySources(ids).groupBy{it.sourceId}else emptyMap();val m=if(main)links.mainBySources(ids).groupBy{it.sourceId}else emptyMap();val a=if(active)links.activeBySources(ids).groupBy{it.sourceId}else emptyMap();val d=if(sdkData)sdk.bySources(ids).groupBy{it.sourceId}else emptyMap();page.forEach{s->result+=MetricFact(s,c[s.id].orEmpty(),i[s.id].orEmpty(),m[s.id].orEmpty(),a[s.id].orEmpty(),d[s.id].orEmpty())};after=page.last().id;if(page.size<500)break};return result}
 private fun facts(start:LocalDateTime,end:LocalDateTime,identity:Boolean=false,main:Boolean=false,active:Boolean=false,sdkData:Boolean=false):List<MetricFact>{val result=mutableListOf<MetricFact>();var after=0L;while(true){val page=sources.pageBetween(start,end,after,500);if(page.isEmpty())break;val ids=page.map{it.id};val c=contents.bySources(ids).groupBy{it.sourceId};val i=if(identity)identities.bySources(ids).groupBy{it.sourceId}else emptyMap();val m=if(main)links.mainBySources(ids).groupBy{it.sourceId}else emptyMap();val a=if(active)links.activeBySources(ids).groupBy{it.sourceId}else emptyMap();val d=if(sdkData)sdk.bySources(ids).groupBy{it.sourceId}else emptyMap();page.forEach{s->result+=MetricFact(s,c[s.id].orEmpty(),i[s.id].orEmpty(),m[s.id].orEmpty(),a[s.id].orEmpty(),d[s.id].orEmpty())};after=page.last().id;if(page.size<500)break};return result}
 private fun valid(c:MetricContentPo)=!c.deleted&&c.maskingStatus=="PASS"
 private fun <T> percentage(items:List<T>,test:(T)->Boolean)=if(items.isEmpty())0.0 else 100.0*items.count(test)/items.size
 private fun clusterMap(ids:List<Long>)=ids.distinct().chunked(500).flatMap(clusters::byIds).associateBy{it.id}
 private fun contactCandidates(all:List<MetricFact>):Double{val groups=mutableMapOf<Pair<String,Long>,MutableList<MetricFact>>();all.forEach{f->if(f.contents.none(::valid))return@forEach;f.identities.filter{it.identityType in setOf("PHONE","EMAIL")}.forEach{i->f.mainLinks.forEach{l->groups.getOrPut(i.fingerprint to l.clusterId){mutableListOf()}+=f}}};return groups.values.count{g->g.map{it.source.id}.distinct().size>=3&&g.map{it.source.sourceChannel}.distinct().size>=2}.toDouble()}
 private fun resolvedCandidates(all:List<MetricFact>,criticalOnly:Boolean):Double{val clusterMap=clusterMap(all.flatMap{it.activeLinks}.map{it.clusterId});val grouped=mutableMapOf<Long,MutableList<MetricFact>>();all.forEach{f->if(f.identities.isEmpty()||f.contents.none{valid(it)&&(!criticalOnly||it.severity in setOf("S0","S1"))})return@forEach;f.activeLinks.forEach{l->val c=clusterMap[l.clusterId];if(c?.status=="RESOLVED"&&f.source.ingestTime?.let{t->c.statusChangedAt?.let{t>it}}==true)grouped.getOrPut(l.clusterId){mutableListOf()}+=f}};return grouped.values.count{g->g.map{it.source.id}.distinct().size>=3&&g.flatMap{it.identities}.map{it.fingerprint}.distinct().size>=2}.toDouble()}
 private fun devicePersistent(all:List<MetricFact>,cutoff:LocalDateTime):Double{val groups=mutableMapOf<Pair<String,Long>,MutableList<MetricFact>>();all.forEach{f->if(f.contents.none(::valid))return@forEach;f.identities.filter{it.identityScope=="DEVICE"}.forEach{i->f.mainLinks.forEach{l->groups.getOrPut(i.fingerprint to l.clusterId){mutableListOf()}+=f}}};return groups.values.count{g->g.map{it.source.id}.distinct().size>=5||g.sumOf{f->if(f.source.ingestTime?.let{it>=cutoff}==true)f.contents.count(::valid)else 0}>=3}.toDouble()}
 private fun publicNegative(all:List<MetricFact>):Double{val groups=mutableMapOf<Long,MutableSet<Long>>();all.filter{it.source.sourceChannel=="REDBLACK"&&it.contents.any{c->valid(c)&&c.sentiment=="NEGATIVE"}}.forEach{f->f.mainLinks.forEach{groups.getOrPut(it.clusterId){mutableSetOf()}+=f.source.id}};return groups.values.count{it.size>=5}.toDouble()}
 private fun userRisk(all:List<MetricFact>,kind:String):Double{val patterns=when(kind){"SAFETY"->Regex("漏电|冒烟|起火|过热|触电|爆炸|爆屏|电池鼓包|烫手|外壳变形|冒火|自燃");"PRIVACY"->Regex("隐私泄露|账号泄露|账号被盗|密码泄露|验证码|个人信息.{0,6}泄露|数据泄露|远程控制|被监控|窃听|录音.{0,6}泄露|位置泄露");"BRICK"->Regex("无法开机|卡logo|卡在logo|进不了系统|无法启动|变砖|黑屏|无法进入|开机.{0,4}失败|白屏|无限重启");"LOSS"->Regex("数据丢失|学习记录丢失|记录清空|数据清空|记录没了|进度丢失|全部丢失|不可恢复|记录.{0,4}不见|成绩.{0,4}丢失|历史.{0,4}清空");else->Regex("暴力|色情|恐怖|血腥|诈骗|低俗|自杀|危险动作|不当内容|不安全|辱骂|仇恨|赌博")};val upgrade=Regex("升级后|更新后|升级完|系统升级|固件升级|OTA|升级失败");return all.count{f->f.contents.any{c->valid(c)&&when(kind){"SAFETY"->c.severity=="S0"&&c.issueCategory in setOf("HARDWARE","BUG")&&patterns.containsMatchIn(c.description.orEmpty());"PRIVACY"->c.severity in setOf("S0","S1")&&patterns.containsMatchIn(c.description.orEmpty());"BRICK"->f.source.appVersion!=null&&c.severity in setOf("S0","S1")&&upgrade.containsMatchIn(c.description.orEmpty())&&patterns.containsMatchIn(c.description.orEmpty());"LOSS"->c.severity in setOf("S0","S1")&&patterns.containsMatchIn(c.description.orEmpty());else->c.issueCategory=="CONTENT_ERROR"&&c.severity in setOf("S0","S1")&&patterns.containsMatchIn(c.description.orEmpty())}}}.toDouble()}
 private fun deviceWide(all:List<MetricFact>):Double{val groups=mutableMapOf<String,MutableList<MetricFact>>();all.forEach{f->if(f.contents.none{valid(it)&&it.severity in setOf("S0","S1")}||f.identities.none{it.identityScope=="DEVICE"})return@forEach;f.sdk.mapNotNull{it.deviceModel}.forEach{groups.getOrPut(it){mutableListOf()}+=f}};return groups.values.count{g->g.flatMap{it.identities}.filter{it.identityScope=="DEVICE"}.map{it.fingerprint}.distinct().size>=10&&g.map{it.source.sourceChannel}.distinct().size>=2}.toDouble()}
 private fun clusterIdentityCandidates(all:List<MetricFact>,sourcesNeeded:Int,fingerprints:Int):Double{val groups=mutableMapOf<Long,MutableList<MetricFact>>();all.filter{it.identities.isNotEmpty()}.forEach{f->f.mainLinks.forEach{groups.getOrPut(it.clusterId){mutableListOf()}+=f}};return groups.values.count{g->g.map{it.source.id}.distinct().size>=sourcesNeeded&&g.flatMap{it.identities}.map{it.fingerprint}.distinct().size>=fingerprints}.toDouble()}
 private fun clusterSourceCandidates(all:List<MetricFact>,sourcesNeeded:Int,channels:Int):Double{val groups=mutableMapOf<Long,MutableList<MetricFact>>();all.forEach{f->f.mainLinks.forEach{groups.getOrPut(it.clusterId){mutableListOf()}+=f}};return groups.values.count{g->g.map{it.source.id}.distinct().size>=sourcesNeeded&&g.map{it.source.sourceChannel}.distinct().size>=channels}.toDouble()}
}
